{"@context":"https://schema.org","@type":"ProfessionalService","name":"Divine Spiritual Guidance","description":"Personalized prophetic words, prophetic blessings and biblical spiritual guidance delivered online in 24-48 hours.","url":"https://propheticguidance2026.blogspot.com/","image":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=1200&q=80","priceRange":"$5-$30","areaServed":{"@type":"Place","name":"Worldwide"},"provider":{"@type":"Person","name":"John S.","jobTitle":"Prophetic Word Specialist & Spiritual Advisor"},"contactPoint":{"@type":"ContactPoint","telephone":"+216-93-816-607","contactType":"customer service","availableLanguage":["English"]},"aggregateRating":{"@type":"AggregateRating","ratingValue":"5.0","reviewCount":"490","bestRating":"5"},"hasOfferCatalog":{"@type":"OfferCatalog","name":"Prophetic Word Services","itemListElement":[{"@type":"Offer","price":"20","priceCurrency":"USD","itemOffered":{"@type":"Service","name":"Divine Word for Your Life in 2026"}},{"@type":"Offer","price":"20","priceCurrency":"USD","itemOffered":{"@type":"Service","name":"Prophetic Blessings for 2026"}},{"@type":"Offer","price":"5","priceCurrency":"USD","itemOffered":{"@type":"Service","name":"Spiritual Biblical Word for Your Life"}},{"@type":"Offer","price":"30","priceCurrency":"USD","itemOffered":{"@type":"Service","name":"Prophetic Word for Your Life"}}]},"offers":{"@type":"AggregateOffer","lowPrice":"5","highPrice":"30","priceCurrency":"USD","offerCount":"4"}}
