head.b:skin:
/*
<Group description="Layout" selector="body">
<Variable name="body.width" description="Content width" type="length" default="1200px" value="1200px"/>
</Group>
*/
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#1f2333;background:#f7f8fc;line-height:1.65;-webkit-font-smoothing:antialiased}
img{max-width:100%;display:block}
a{color:#1a2a6c;text-decoration:none}
.wrap{max-width:1200px;margin:0 auto;padding:0 18px}
.hdr{position:sticky;top:0;z-index:99;background:rgba(255,255,255,.96);backdrop-filter:blur(10px);box-shadow:0 1px 12px rgba(26,42,108,.09)}
.hdr .wrap{display:flex;align-items:center;justify-content:space-between;height:64px}
.logo{font-weight:800;font-size:18px;color:#1a2a6c;letter-spacing:-.3px}
.logo span{color:#d4af37}
.nav{display:flex;gap:22px}
.nav a{font-size:15px;font-weight:600;color:#3a4160}
.nav a:hover{color:#d4af37}
.mtog{display:none;background:none;border:0;font-size:26px;line-height:1;color:#1a2a6c;cursor:pointer;padding:6px 10px}
.mnav{display:none;flex-direction:column;background:#fff;border-top:1px solid #eceffa}
.mnav a{padding:14px 20px;font-weight:600;border-bottom:1px solid #f2f4fb;color:#3a4160}
.mnav.open{display:flex}
@media(max-width:860px){.nav{display:none}.mtog{display:block}}
.hero{background:linear-gradient(135deg,#1a2a6c 0%,#2d3a8c 45%,#4b3fa8 100%);color:#fff;padding:64px 0 72px;text-align:center}
.hero h1{font-size:34px;line-height:1.22;font-weight:800;max-width:900px;margin:0 auto 18px;letter-spacing:-.5px}
.hero p{font-size:17px;max-width:760px;margin:0 auto 20px;color:#e2e6ff}
.stars{color:#d4af37;font-size:19px;letter-spacing:2px}
.rate{margin-bottom:22px;font-weight:600;color:#fff}
.btn{display:inline-block;background:linear-gradient(135deg,#d4af37,#f0c95a);color:#1a2a6c;font-weight:800;padding:14px 30px;border-radius:14px;font-size:16px;box-shadow:0 8px 22px rgba(212,175,55,.35)}
.btn:hover{transform:translateY(-2px)}
.sec{padding:56px 0}
.sec h2{font-size:27px;font-weight:800;text-align:center;color:#1a2a6c;margin-bottom:10px;letter-spacing:-.4px}
.sub{text-align:center;color:#5d6480;max-width:680px;margin:0 auto 32px}
.grid4{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.grid2{display:grid;grid-template-columns:1fr;gap:20px}
.grid3{display:grid;grid-template-columns:1fr;gap:18px}
@media(min-width:700px){.grid2{grid-template-columns:repeat(2,1fr)}.grid3{grid-template-columns:repeat(2,1fr)}}
@media(min-width:1000px){.grid4{grid-template-columns:repeat(4,1fr)}.grid2{grid-template-columns:repeat(4,1fr)}.grid3{grid-template-columns:repeat(3,1fr)}}
.card{background:#fff;border-radius:16px;box-shadow:0 4px 18px rgba(26,42,108,.08);overflow:hidden}
.feat{padding:22px 18px;text-align:center}
.feat .ic{font-size:30px;margin-bottom:8px}
.feat h3{font-size:16px;color:#1a2a6c;margin-bottom:6px}
.feat p{font-size:14px;color:#5d6480}
.svc img{width:100%;height:190px;object-fit:cover}
.svc .bd{padding:18px}
.svc h3{font-size:18px;color:#1a2a6c;margin-bottom:8px}
.svc p{font-size:14.5px;color:#4d5470;margin-bottom:12px}
.price{font-size:24px;font-weight:800;color:#d4af37;margin:10px 0}
.btn.sm{padding:11px 20px;font-size:14.5px;width:100%;text-align:center}
.tst{padding:22px}
.tst p{font-size:15px;color:#4d5470;font-style:italic;margin:10px 0}
.tst .who{font-weight:700;color:#1a2a6c;font-size:14.5px}
.about{background:#fff;border-radius:20px;padding:30px 24px;box-shadow:0 4px 18px rgba(26,42,108,.08)}
.badges{display:flex;flex-wrap:wrap;gap:10px;justify-content:center;margin-bottom:18px}
.badge{background:#eef1ff;color:#1a2a6c;font-weight:700;font-size:13.5px;padding:8px 14px;border-radius:999px}
.about ul{list-style:none;margin:16px 0}
.about li{padding:6px 0;color:#3a4160}
.quote{font-style:italic;color:#5d6480;border-left:4px solid #d4af37;padding-left:14px;margin-top:16px}
details{background:#fff;border-radius:14px;padding:16px 18px;margin-bottom:12px;box-shadow:0 3px 14px rgba(26,42,108,.07)}
summary{font-weight:700;color:#1a2a6c;cursor:pointer;font-size:16px;list-style:none}
summary::-webkit-details-marker{display:none}
summary:after{content:"\002B";float:right;color:#d4af37;font-weight:800}
details[open] summary:after{content:"\2212"}
details p{margin-top:10px;color:#4d5470;font-size:15px}
.cta{background:linear-gradient(135deg,#1a2a6c,#4b3fa8);color:#fff;text-align:center;padding:52px 18px;border-radius:22px;margin:20px auto}
.cta h2{color:#fff;font-size:26px;margin-bottom:12px}
.cta p{color:#dfe3ff;margin-bottom:20px}
.post{padding:18px}
.post h3{font-size:17px;color:#1a2a6c;margin-bottom:8px}
.post p{font-size:14.5px;color:#5d6480;margin-bottom:10px}
.rm{font-weight:700;color:#d4af37}
footer{background:#141a3a;color:#c7cbe6;padding:40px 0 26px;margin-top:40px}
footer .fn{display:flex;flex-wrap:wrap;gap:16px;justify-content:center;margin-bottom:16px}
footer .fn a{color:#c7cbe6;font-size:14.5px}
footer .fn a:hover{color:#d4af37}
.disc{font-size:13px;color:#8a90b5;text-align:center;max-width:720px;margin:0 auto 12px}
.cp{text-align:center;font-size:13px;color:#8a90b5}
.wa{position:fixed;right:16px;bottom:16px;width:56px;height:56px;border-radius:50%;background:#25d366;color:#fff;font-size:26px;display:flex;align-items:center;justify-content:center;box-shadow:0 8px 22px rgba(37,211,102,.45);z-index:120}
@media(min-width:700px){.hero h1{font-size:44px}.hero{padding:88px 0 96px}.sec h2{font-size:33px}}

body.script:
//
(function(){
  var t=document.getElementById('mtog'),m=document.getElementById('mnav');
  if(t&&m){t.addEventListener('click',function(){m.classList.toggle('open');});
  m.addEventListener('click',function(e){if(e.target.tagName==='A'){m.classList.remove('open');}});}
  document.addEventListener('click',function(e){
    var a=e.target.closest('a');
    if(!a)return;
    var h=a.getAttribute('href');
    if(h&&h.charAt(0)==='#'&&h.length>1){
      var el=document.querySelector(h);
      if(el){e.preventDefault();window.scrollTo({top:el.offsetTop-70,behavior:'smooth'});}
    }
  });
})();
//
